import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, Integer> stok = new LinkedHashMap<String, Integer>();
        stok.put("Apel", 10);
        stok.put("Jeruk", 5);
        stok.put("Melon", 3);

        for (String k : stok.keySet()) {
            System.out.println(k + " = " + stok.get(k));
        }

        int total = 0;
        for (int n : stok.values()) {
            total += n;
        }
        System.out.println("Total stok: " + total);

        for (Map.Entry<String, Integer> e : stok.entrySet()) {
            if (e.getValue() < 5) {
                System.out.println("Menipis: " + e.getKey());
            }
        }
    }
}

